#!/usr/bin/env bash
# Write the OpenAPI document of a locally loaded Sentinel image to OUTPUT_FILE.
# backend/scripts/generate_openapi.py runs inside the image, so the document is
# generated by the application code and dependencies the image ships.
# Usage: scripts/extract-openapi.sh IMAGE OUTPUT_FILE

set -euo pipefail

main() {
    if [[ $# -ne 2 ]]; then
        echo "Usage: $0 IMAGE OUTPUT_FILE" >&2
        return 2
    fi

    local image="$1"
    local output_file="$2"
    local script_dir repo_root

    script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    repo_root="$(dirname "${script_dir}")"

    mkdir -p "$(dirname "${output_file}")"
    # The generator needs neither network access nor another image.
    docker run --rm --interactive --network none --pull never \
        "${image}" python - \
        <"${repo_root}/backend/scripts/generate_openapi.py" \
        >"${output_file}"

    # --slurp: a log line printed before the document must not pass.
    if ! jq -e --slurp '
        length == 1
        and (.[0].openapi | type == "string")
        and (.[0].info.version | type == "string")
        and (.[0].paths | type == "object")
    ' "${output_file}" >/dev/null 2>&1; then
        echo "Not an OpenAPI document: ${output_file}" >&2
        return 1
    fi
}

main "$@"
